catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
  debugger;
  if (isLoading) {
    return;
  }

  g_form.hideFieldMsg("fingerprint_campo", true);
  if (newValue == "") {
    g_form.setValue("fingerprint_dup_check", "");
    return;
  }
  g_form.setValue("fingerprint_dup_check", "pending");

  var fingerprint = g_form.getValue("fingerprint_campo");

  var ga = new GlideAjax("sn_disco_certmgmt.BNB_Verifica_Duplicidade_Certificado");
  ga.addParam("sysparm_name", "checkDuplicate");
  ga.addParam("sysparm_fingerprint", fingerprint);
  ga.getXMLAnswer(function (answer) {
    // Resposta antiga: o usuário já alterou o campo
    if (g_form.getValue("fingerprint_campo") != fingerprint) {
      return;
    }
    try {
      var result = JSON.parse(answer);
      g_form.setValue("fingerprint_dup_check", result.status);
      if (result.status == "OK") {
        if (result.formatted != fingerprint) {
          g_form.setValue("fingerprint_campo", result.formatted);
        }
      } else {
        g_form.showFieldMsg("fingerprint_campo", result.message, "error");
      }
    } catch (e) {
      g_form.setValue("fingerprint_dup_check", "ERROR");
      g_form.showFieldMsg(
        "fingerprint_campo",
        "Erro ao verificar duplicidade do Fingerprint. " + e.message,
        "error",
      );
    }
  });
  return true;
}
